def check_power(k, min_exp):
    """Checks if k is a prime power p^A where A >= min_exp."""
    if k <= 1:
        return None, 0

    # Optimization: check if k is a power of 2 first, as it's often the smallest prime.
    if k > 0 and (k & (k - 1)) == 0:
        p = 2
        exponent = k.bit_length() - 1
        if exponent >= min_exp:
            return p, exponent

    # Iterate through possible bases p
    # We only need to check primes up to k, but for A>=2, the base must be <= sqrt(k)
    # Or we can iterate over all potential prime bases.

    # We use a simpler approach: test all potential bases starting from 2 up to k

    # Since we require A >= 2, we only need to check potential bases up to k**(1/2)
    limit = int(k**0.5) + 2

    for p in range(2, limit):
        if k % p == 0:
            temp = k
            exponent = 0
            while temp > 0 and temp % p == 0:
                temp //= p
                exponent += 1

            if temp == 1:
                # k is a power of p
                if exponent >= min_exp:
                    return p, exponent

    return None, 0

def find_solutions(M_max, N_max):
    solutions = []
    for m in range(1, M_max + 1):
        for n in range(1, N_max + 1):
            m2_plus_n = m*m + n
            m_plus_n2 = m + n*n

            # Check m^2 + n = p^A, A >= 2
            p_A, A = check_power(m2_plus_n, 2)

            if p_A is not None:
                # Check m + n^2 = p^B, B >= 2
                p_B, B = check_power(m_plus_n2, 2)

                if p_B is not None and p_A == p_B:
                    p = p_A
                    solutions.append((m, n, p, A, B)) # Storing A and B now

    return solutions

# Searching up to m, n = 30
solutions_large = find_solutions(30, 30)
print(f"Solutions found up to m, n = 30: {solutions_large}")

def check_solution(m, n, p):
    if m <= 0 or n <= 0 or not isinstance(p, int) or p <= 1:
        return False

    import math

    def is_power_of_p(k, p):
        if k <= 0:
            return False
        if p == 1:
            return k == 1

        if k == 1:
            return True # p^0

        temp_k = k
        while temp_k > 1:
            if temp_k % p != 0:
                return False
            temp_k //= p
        return True

    # Check constraints

    # Constraint 1: m^2 + n = p^a, a >= 2
    term1 = m**2 + n
    is_pow1 = is_power_of_p(term1, p)
    if is_pow1:
        # Check a >= 2
        if term1 <= p:
            is_a_ge_2 = False
        else:
            is_a_ge_2 = True
    else:
        is_a_ge_2 = False

    # Constraint 2: m + n^2 = p^b, b >= 2
    term2 = m + n**2
    is_pow2 = is_power_of_p(term2, p)
    if is_pow2:
        # Check b >= 2
        if term2 <= p:
            is_b_ge_2 = False
        else:
            is_b_ge_2 = True
    else:
        is_b_ge_2 = False

    return is_a_ge_2 and is_b_ge_2

